B.b7S=new A.ac(B.c4,B.atQ,"Horno a 200 \xb0C.","La carne de la berenjena est\xe1 blanda (20-25 minutos asadas) y el queso gratinado (5 minutos m\xe1s).",B.ayj,B.arc,B.axR,"3 d\xedas en la nevera.",null,B.r)
B.au8=s(["Sart\xe9n","Bol grande"],t.s)
B.asz=s(["Picatostes: el pan en dados con un poco de aceite, 3-4 minutos en sart\xe9n o air fryer.","Ali\xf1a justo al servir."],t.s)
B.aQ5=s(["Salsa C\xe9sar \u2192 yogur, parmesano, lim\xf3n y un poco de mostaza."],t.s)
B.b8u=new A.ac(B.t,B.au8,null,"Pollo dorado y picatostes crujientes.",B.asz,B.j,B.aQ5,null,null,B.r)
B.aFJ=s(["Olla","Bol grande","Tenedor"],t.s)
B.aqZ=s(["Cuece las patatas con piel: no se empapan y quedan con m\xe1s sabor.","Mezcla con la patata fr\xeda: si est\xe1 caliente, la mayonesa se corta."],t.s)
